import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

/**
 * Two parts, and that is the whole component. The boxes are `checkbox`es — a
 * checkbox exists on its own, unlike a radio, so there is nothing here to
 * re-implement as `item*` parts.
 */
export type CheckboxGroupPart = "root" | "label";

export const anatomy: Anatomy<CheckboxGroupPart> = createAnatomy("checkbox-group").parts(
  "root",
  "label",
);

export const parts: Record<CheckboxGroupPart, AnatomyPart> = anatomy.build();

import { ariaAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { parts } from "./checkbox-group.anatomy";
import { getGroupName, getLabelId, getRootId } from "./checkbox-group.dom";
import type { CheckboxGroupApi, CheckboxGroupSchema } from "./checkbox-group.types";

export function connect<T extends PropTypes>(
  service: Service<CheckboxGroupSchema>,
  normalize: NormalizeProps<T>,
): CheckboxGroupApi<T> {
  const { context, prop, computed, send, scope } = service;

  const value = context.get("value");
  const disabled = prop("disabled");
  const readOnly = prop("readOnly");
  const invalid = prop("invalid");
  const required = prop("required");
  const orientation = prop("orientation");

  return {
    value,
    name: getGroupName(scope, prop("name")),
    disabled,
    readOnly,
    invalid,
    form: prop("form"),
    parentChecked: computed("parentChecked"),
    parentDisabled: computed("parentDisabled"),

    isChecked: (entry: string): boolean => value.includes(entry),

    setValue(next: readonly string[]): void {
      send({ type: "VALUE.SET", value: next });
    },
    toggleValue(entry: string): void {
      send({ type: "ITEM.TOGGLE", value: entry });
    },
    toggleAll(checked: boolean): void {
      send({ type: "PARENT.TOGGLE", checked });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: getRootId(scope),
        role: "group",
        dir: prop("dir"),
        // Only when it exists: a dangling IDREF names the group nothing at all,
        // which is the defect the Phase 4 audit found on `progress`.
        "aria-labelledby": context.get("hasLabel") ? getLabelId(scope) : undefined,
        "aria-describedby": prop("describedBy"),
        "aria-invalid": ariaAttr(invalid),
        "aria-disabled": ariaAttr(disabled),
        // `aria-required` is deliberately absent. It is not an allowed attribute
        // on `role="group"` (axe flags it), and the native spelling is worse: a
        // `required` checkbox means *this box* must be checked, so putting it on
        // the items would demand all of them instead of at least one. The rule
        // belongs to the consumer's validation; the group only says it exists.
        "data-required": dataAttr(required),
        "data-orientation": orientation,
        "data-disabled": dataAttr(disabled),
        "data-readonly": dataAttr(readOnly),
        "data-invalid": dataAttr(invalid),
        style: { "--sui-item-count": String(Math.max(context.get("itemCount"), 1)) },
      }),

    getLabelProps: (): T["element"] =>
      normalize.element({
        ...parts.label.attrs,
        id: getLabelId(scope),
        "data-disabled": dataAttr(disabled),
        "data-invalid": dataAttr(invalid),
      }),
  };
}

import { query, queryAll } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "checkbox-group";

/**
 * The one character an attribute value cannot carry — the HTML parser rewrites it
 * to U+FFFD — so two different item lists can never key the same. Written as an
 * escape rather than typed: the raw byte makes ripgrep classify the file as
 * binary and skip it, which once hid two of the ten machines from every grep in
 * the repo.
 */
const SEPARATOR = "\u0000";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

/**
 * Unique by construction, so two groups on one page never submit into each
 * other's field — the same reason `radio-group` derives one.
 */
export function getGroupName(scope: Scope, name: string | undefined): string {
  return name ?? getRootId(scope);
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

/**
 * `aria-labelledby` may only point at an id that exists.
 *
 * The qualification this used to spell out by hand is now the identity itself:
 * this component contains other components, and every checkbox in it has a
 * `label` part of its own, so a search for a bare `label` finds the first box's
 * and names the group after it.
 */
export function hasLabel(scope: Scope): boolean {
  return query(getRootEl(scope), `[data-part~="${COMPONENT}:label"]`) !== null;
}

/**
 * The items, read from the DOM and never registered — a group that has to be told
 * about its own children goes out of sync the first time one is rendered
 * conditionally (the lesson `toggle-group` and `radio-group` are both built on).
 *
 * An item is a checkbox submitting under this group's name. That is not a
 * convention invented for the lookup: submitting together under one name is what
 * makes several boxes one field. It also settles which box is the tri-state
 * summary without needing a flag — the summary submits nothing, so it carries no
 * name and is not found here.
 *
 * The name is compared in JS rather than in the selector: matching it there needs
 * `CSS.escape`, and reaching a window from a pure DOM helper to get it buys
 * nothing over one string comparison.
 */
export function getItemInputEls(scope: Scope, name: string): HTMLInputElement[] {
  const root = getRootEl(scope);
  if (root === null) return [];
  return queryAll<HTMLInputElement>(root, 'input[type="checkbox"]').filter(
    (input) => input.name === name,
  );
}

/**
 * The dependency a `watch` compares — the items *and* whether each is reachable,
 * because disabling one changes what the summary is a summary of.
 */
export function getItemKey(scope: Scope, name: string): string {
  return getItemInputEls(scope, name)
    .map((input) => `${input.disabled ? "-" : "+"}${input.value}`)
    .join(SEPARATOR);
}

/**
 * A checkbox group is not a composite. APG makes it a `group` of independent tab
 * stops — no roving, no arrow keys, Space on each box — so there is no focus
 * machinery here at all, and no modality to track: every box already reports its
 * own.
 *
 * What is left is the two things a set of checkboxes cannot do for itself. It
 * owns the array of checked values, so several boxes submit as one field. And it
 * derives the tri-state summary, which is the whole reason the component exists.
 *
 * The summary is computed over the items the user can actually toggle. A
 * disabled item is excluded from both the reading and the writing: a parent that
 * says "mixed" when the only unchecked box is disabled would be a parent nobody
 * can resolve, and one that "selects all" by flipping a box the user cannot flip
 * would be doing something the user is not allowed to do. So the summary means
 * "everything you can toggle is on", and a disabled item keeps whatever state it
 * was given.
 */

import { observeChildren } from "../../dom/observers";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import {
  getGroupName,
  getItemInputEls,
  getItemKey,
  getRootEl,
  hasLabel,
} from "./checkbox-group.dom";
import type { CheckboxGroupSchema } from "./checkbox-group.types";

export const machine: Machine<CheckboxGroupSchema> = createMachine<CheckboxGroupSchema>({
  props({ props }) {
    return {
      orientation: "vertical",
      disabled: false,
      readOnly: false,
      invalid: false,
      required: false,
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      value: bindable<readonly string[]>(() => ({
        defaultValue: prop("defaultValue") ?? [],
        value: prop("value"),
        // Order is not meaning: a group that reported a change because the same
        // values arrived in another order would loop against a consumer that
        // normalises them.
        isEqual: (a, b) => a.length === b.length && a.every((entry) => b.includes(entry)),
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "checkbox-group value",
      })),
      enabledValues: bindable<readonly string[]>(() => ({
        defaultValue: [],
        // Order *is* meaning here — it is DOM order — and this list is rewritten
        // on every settle, so it needs an equality that stops the write.
        isEqual: (a, b) => a.length === b.length && a.every((entry, index) => b[index] === entry),
      })),
      itemCount: bindable<number>(() => ({ defaultValue: 0 })),
      hasLabel: bindable<boolean>(() => ({ defaultValue: false })),
    };
  },

  computed: {
    parentChecked({ context }) {
      const enabled = context.get("enabledValues");
      if (enabled.length === 0) return false;
      const value = context.get("value");
      const checked = enabled.filter((entry) => value.includes(entry)).length;
      if (checked === 0) return false;
      return checked === enabled.length ? true : "indeterminate";
    },
    // Nothing to summarise is not the same as an unchecked summary: a box that
    // does nothing when pressed is worse than one that says it cannot be.
    parentDisabled: ({ prop, context }) =>
      prop("disabled") || context.get("enabledValues").length === 0,
  },

  initialState() {
    return "idle";
  },

  effects: ["trackItems"],

  watch({ context, prop, scope, track, action }) {
    // The item list is a dependency like any other. Reading it here keeps the
    // summary in step synchronously with a render, and leaves the observer below
    // to cover the mutations no render caused.
    track(
      () => [context.get("value"), getItemKey(scope, getGroupName(scope, prop("name")))],
      () => action(["syncItems"]),
    );
  },

  on: {
    "ITEM.TOGGLE": { guard: "isInteractive", actions: ["toggleItem"] },
    "PARENT.TOGGLE": { guard: "isInteractive", actions: ["toggleAll"] },
    "VALUE.SET": { actions: ["setValue"] },
    "ITEMS.SYNC": { actions: ["syncItems"] },
  },

  states: {
    idle: {},
  },

  implementations: {
    guards: {
      // Read-only is not disabled: the boxes stay focusable and announced, they
      // simply refuse to change — which is what a form in review mode wants.
      isInteractive: ({ prop }) => !prop("disabled") && !prop("readOnly"),
    },

    actions: {
      toggleItem({ context, event }) {
        if (event.type !== "ITEM.TOGGLE") return;
        const value = context.get("value");
        context.set(
          "value",
          value.includes(event.value)
            ? value.filter((entry) => entry !== event.value)
            : [...value, event.value],
        );
      },

      toggleAll({ context, event }) {
        if (event.type !== "PARENT.TOGGLE") return;
        const next = new Set(context.get("value"));
        for (const entry of context.get("enabledValues")) {
          if (event.checked) next.add(entry);
          else next.delete(entry);
        }
        // A disabled item's value survives both branches: it was never the
        // summary's to give or to take.
        context.set("value", [...next]);
      },

      setValue({ context, event }) {
        if (event.type === "VALUE.SET") context.set("value", event.value);
      },

      syncItems({ context, prop, scope }) {
        const inputs = getItemInputEls(scope, getGroupName(scope, prop("name")));
        context.set("itemCount", inputs.length);
        context.set(
          "enabledValues",
          inputs.filter((input) => !input.disabled).map((input) => input.value),
        );
        context.set("hasLabel", hasLabel(scope));
      },
    },

    effects: {
      trackItems({ scope, send }) {
        send({ type: "ITEMS.SYNC" });
        // Items appear and disappear with the app's own state, and the summary
        // has to survive that without the consumer telling anyone. A box merely
        // becoming disabled is an attribute change this observer does not watch —
        // that one arrives through the `watch` above, on the settle that caused it.
        return observeChildren(getRootEl(scope), () => send({ type: "ITEMS.SYNC" }));
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, Orientation } from "../../types";
import type { CheckedState } from "../checkbox/checkbox.types";

export interface CheckboxGroupValueChangeDetails {
  readonly value: readonly string[];
}

export interface CheckboxGroupMachineProps {
  readonly dir?: Direction | undefined;
  readonly orientation?: Orientation | undefined;
  readonly value?: readonly string[] | undefined;
  readonly defaultValue?: readonly string[] | undefined;
  readonly disabled?: boolean | undefined;
  readonly readOnly?: boolean | undefined;
  readonly invalid?: boolean | undefined;
  /**
   * "At least one" — never spelled `required` on the boxes themselves, where the
   * browser would read it as "this one".
   */
  readonly required?: boolean | undefined;
  /** Shared by every item, and how the group finds them. Derived from the id when absent. */
  readonly name?: string | undefined;
  readonly form?: string | undefined;
  /** Ids of the text describing this group — a `field` supplies them. */
  readonly describedBy?: string | undefined;
  readonly onValueChange?: ((details: CheckboxGroupValueChangeDetails) => void) | undefined;
}

export interface ResolvedCheckboxGroupMachineProps extends CheckboxGroupMachineProps {
  readonly orientation: Orientation;
  readonly disabled: boolean;
  readonly readOnly: boolean;
  readonly invalid: boolean;
  readonly required: boolean;
}

export interface CheckboxGroupSchema extends MachineSchema {
  state: "idle";
  props: ResolvedCheckboxGroupMachineProps;
  context: {
    value: readonly string[];
    /** Item values the user can actually reach — the summary is computed over these. */
    enabledValues: readonly string[];
    itemCount: number;
    hasLabel: boolean;
  };
  computed: { parentChecked: CheckedState; parentDisabled: boolean };
  event:
    | { type: "ITEM.TOGGLE"; value: string }
    | { type: "VALUE.SET"; value: readonly string[] }
    | { type: "PARENT.TOGGLE"; checked: boolean }
    | { type: "ITEMS.SYNC" };
  action: "toggleItem" | "setValue" | "toggleAll" | "syncItems";
  guard: "isInteractive";
  effect: "trackItems";
}

export interface CheckboxGroupApi<T extends PropTypes = PropTypes> {
  readonly value: readonly string[];
  /** Every item carries it, and it is what makes them items. */
  readonly name: string;
  readonly disabled: boolean;
  readonly readOnly: boolean;
  readonly invalid: boolean;
  readonly form: string | undefined;
  /** The summary over the items the user can toggle, in a checkbox's own vocabulary. */
  readonly parentChecked: CheckedState;
  readonly parentDisabled: boolean;
  isChecked(value: string): boolean;
  setValue(value: readonly string[]): void;
  toggleValue(value: string): void;
  toggleAll(checked: boolean): void;
  getRootProps(): T["element"];
  getLabelProps(): T["element"];
}

export { anatomy, type CheckboxGroupPart, parts } from "./checkbox-group.anatomy";
export { connect } from "./checkbox-group.connect";
export {
  getGroupName,
  getItemInputEls,
  getItemKey,
  getLabelId,
  getRootEl,
  getRootId,
} from "./checkbox-group.dom";
export { machine } from "./checkbox-group.machine";
export type {
  CheckboxGroupApi,
  CheckboxGroupMachineProps,
  CheckboxGroupSchema,
  CheckboxGroupValueChangeDetails,
  ResolvedCheckboxGroupMachineProps,
} from "./checkbox-group.types";

import * as checkboxGroup from "@standarui/core/checkbox-group";
import type { ReactNode } from "react";
import { CheckboxGroupContext } from "../../checkbox-group-context";
import { createPart, type PartProps } from "../../create-part";
import { inheritFromField, useFieldContext } from "../../field-context";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type CheckboxGroupApi = checkboxGroup.CheckboxGroupApi<ReactPropTypes>;

export interface UseCheckboxGroupProps
  extends checkboxGroup.CheckboxGroupMachineProps,
    MachineRuntimeProps {}

export function useCheckboxGroup(props: UseCheckboxGroupProps): CheckboxGroupApi {
  return checkboxGroup.connect(useMachine(checkboxGroup.machine, props), normalizeProps);
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "orientation",
  "value",
  "defaultValue",
  "disabled",
  "readOnly",
  "invalid",
  "required",
  "name",
  "form",
  "describedBy",
  "onValueChange",
] as const;

export interface CheckboxGroupRootProps
  extends UseCheckboxGroupProps,
    PartProps<"div", UseCheckboxGroupProps> {}

/**
 * The boxes are ordinary `<CheckboxRoot>`s — a checkbox exists on its own, so
 * there is nothing to re-declare as item parts here. Each one with a `value` is
 * an item; one without is the tri-state summary (`checkbox-group-context`).
 */
export function CheckboxGroupRoot(props: CheckboxGroupRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const field = useFieldContext();
  const api = useCheckboxGroup(inheritFromField(machineProps, field));

  return (
    <CheckboxGroupContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </CheckboxGroupContext.Provider>
  );
}

export const CheckboxGroupLabel: (props: PartProps<"span">) => ReactNode = createPart(
  CheckboxGroupContext,
  { name: "CheckboxGroupLabel", element: "span", props: (api) => api.getLabelProps() },
);

/**
 * `<CheckboxGroup label="…" options={…}/>` — the field `checkbox-group.stories.tsx`
 * writes by hand: a `CheckboxGroupRoot`, its label, and one full checkbox tree per
 * entry (`CheckboxRoot` > `CheckboxHiddenInput`, `CheckboxControl` >
 * `CheckboxIndicator`, `CheckboxLabel`).
 *
 * The group is not a composite (`checkbox-group.machine.ts`'s header) — every box
 * keeps its own tab stop, so there is nothing here to route focus through and
 * nothing to memoise over the entries. This is a placement, the way `Select`'s
 * options are: the collection is still the live DOM the machine reads, and an
 * array mapped into `<CheckboxRoot>` elements before the render holds nothing.
 *
 * One thing the type system cannot make on its own: an entry with no `value` is
 * the tri-state summary, not an item — `checkbox-group-context.ts`'s "role rule",
 * where a box's `value` is what makes it one. That is why `CheckboxGroupOption`
 * leaves `value` exactly as optional as `CheckboxRootProps` already has it,
 * rather than narrowing it to required the way `SelectOption.value` is.
 */

import type { ReactNode } from "react";
import type { ComposedSeparator } from "../../composed";
import type { PartProps } from "../../create-part";
import {
  CheckboxControl,
  CheckboxHiddenInput,
  CheckboxIndicator,
  CheckboxLabel,
  CheckboxRoot,
  type CheckboxRootProps,
} from "../checkbox/checkbox";
import { SeparatorRoot } from "../separator/separator";
import {
  CheckboxGroupLabel,
  CheckboxGroupRoot,
  type UseCheckboxGroupProps,
} from "./checkbox-group";

/**
 * A box's own props, minus `children`: the composed layer places the checkbox's
 * whole subtree itself, so nothing here can replace it. `label` is what an entry
 * names itself with, the way `SelectOption.label` is — required for the same
 * reason a nameless control is a defect rather than a shape to leave compilable.
 */
export type CheckboxGroupOption = Omit<CheckboxRootProps, "children"> & {
  readonly label: ReactNode;
};

/** Narrowed structurally — `"separator" in entry` — the test `Select` already uses. */
export type CheckboxGroupEntry = CheckboxGroupOption | ComposedSeparator;

export interface CheckboxGroupComposedProps
  extends UseCheckboxGroupProps,
    Omit<PartProps<"div", UseCheckboxGroupProps>, "children"> {
  /**
   * Rendered only when given. `CheckboxGroupRoot`'s `aria-labelledby` is written
   * only once `hasLabel` finds a label part in the DOM
   * (`checkbox-group.dom.ts`/`hasLabel`), so a group left unlabelled here keeps
   * whatever other name it has — an `aria-label` on the root, a `Field`'s own
   * caption — instead of gaining a second, unlinked one.
   */
  readonly label?: ReactNode;
  readonly options: readonly CheckboxGroupEntry[];
}

export function CheckboxGroup(props: CheckboxGroupComposedProps): ReactNode {
  const { label, options, ...root } = props;

  return (
    <CheckboxGroupRoot {...root}>
      {label == null ? null : <CheckboxGroupLabel>{label}</CheckboxGroupLabel>}
      {options.map((entry, index) => {
        // A separator holds no value to key on and no state to preserve across a
        // re-render — the same reasoning `Select`'s composed layer states for its
        // own separators.
        if ("separator" in entry) {
          // biome-ignore lint/suspicious/noArrayIndexKey: safe on a separator, and on nothing else in this list — see above.
          return <SeparatorRoot key={`sep:${index}`} />;
        }
        const { label: boxLabel, ...box } = entry;
        return (
          <CheckboxRoot key={box.value ?? "summary"} {...box}>
            <CheckboxHiddenInput />
            <CheckboxControl>
              <CheckboxIndicator />
            </CheckboxControl>
            <CheckboxLabel>{boxLabel}</CheckboxLabel>
          </CheckboxRoot>
        );
      })}
    </CheckboxGroupRoot>
  );
}

export type {
  CheckboxGroupMachineProps,
  CheckboxGroupValueChangeDetails,
} from "@standarui/core/checkbox-group";
export {
  type CheckboxGroupApi,
  CheckboxGroupLabel,
  CheckboxGroupRoot,
  type CheckboxGroupRootProps,
  type UseCheckboxGroupProps,
  useCheckboxGroup,
} from "./checkbox-group";
export {
  CheckboxGroup,
  type CheckboxGroupComposedProps,
  type CheckboxGroupEntry,
  type CheckboxGroupOption,
} from "./composed";
